using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;using XHLLauncher;
class CompleteMaintenance {
 static int Main(string[] args){try{return Run(args);}catch(Exception ex){File.WriteAllText(Path.Combine(args[1],"Gameplay-resume-error.txt"),ex.ToString());Console.WriteLine("Maintenance held: "+ex.Message);return 1;}}
 static bool Equal(object a,object b){if(a is ValueType&&b is ValueType&&!(a is bool)&&!(b is bool))return Convert.ToDecimal(a)==Convert.ToDecimal(b);return new JavaScriptSerializer().Serialize(a)==new JavaScriptSerializer().Serialize(b);}
 static int Run(string[] args){string app=args[0],output=args[1],original=args[2];var settings=Storage.LoadSettings(app);string path=Path.Combine(settings.ServerRoot,"enshrouded_server.json");if(!Path.GetFullPath(original).StartsWith(path+".before-rules-",StringComparison.OrdinalIgnoreCase))throw new IOException("Original config must be the retained pre-change file.");var js=new JavaScriptSerializer();var before=ConfigurationDocument.Flatten(js.Deserialize<Dictionary<string,object>>(File.ReadAllText(original)));var data=Maintenance.Config(settings.ServerRoot);var after=ConfigurationDocument.Flatten(data);string[] allowed={"gameSettings.foodBuffDurationFactor","gameSettings.miningDamageFactor","gameSettings.plantGrowthSpeedFactor","gameSettings.resourceDropStackAmountFactor","gameSettings.factoryProductionSpeedFactor"};var changed=after.Where(f=>!Equal(f.Value,before.First(x=>x.Path==f.Path).Value)).ToArray();if(changed.Length!=5||after.Count!=before.Count||changed.Any(f=>!allowed.Contains(f.Path)||Convert.ToDecimal(f.Value)!=2))throw new IOException("Unexpected configuration differences; no start allowed.");ConfigurationDocument.ValidateCompatibility(data,data);Console.WriteLine("Verified exactly five semantic changes, all to 2; all other fields preserved.");var runtime=new ExistingServerRuntime(settings.ServerRoot,settings);var lifecycle=new ServerLifecycle(runtime,()=>ServerLifecycle.CheckInstallation(settings.ServerRoot));if(runtime.IsRunning)throw new IOException("Server already running; no duplicate start permitted.");var result=lifecycle.Execute("Start");Console.WriteLine(result.Message);if(!result.Success)return 2;DateTime end=DateTime.UtcNow.AddMinutes(4);while(DateTime.UtcNow<end){Thread.Sleep(1000);if(!runtime.IsRunning)continue;try{var cfg=ConfigReader.Read(settings.ServerRoot);var info=ServerQuery.Read("127.0.0.1",cfg.QueryPort,1000);Console.WriteLine("Game query confirmed: "+info.Name+"; "+info.Players+" / "+info.Capacity);File.WriteAllText(Path.Combine(output,"Gameplay-range-alignment.json"),js.Serialize(new{applied=true,changes=changed.Select(f=>new{path=f.Path,before=before.First(x=>x.Path==f.Path).Value,after=f.Value}).ToArray(),allOtherFieldsPreserved=true,queryConfirmed=true,players=info.Players,previousConfig=original}));return 0;}catch{}}Console.WriteLine("Readiness unconfirmed. No repeated start performed.");return 3;}
}
